{
  "name": "@yasin.herken/opencode-notificator",
  "version": "2.0.1",
  "description": "Desktop notifications and sound alerts for OpenCode V2: when a turn finishes, the agent asks a question, needs permission, or errors.",
  "type": "module",
  "license": "MIT",
  "exports": {
    ".": "./index.js"
  },
  "files": [
    "index.js",
    "notificator.jsonc",
    "README.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "notification",
    "notifications",
    "desktop-notifications",
    "notificator",
    "macos",
    "linux"
  ],
  "engines": {
    "node": ">=20"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.24"
  },
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git://github.com/yasin-herken/opencode-notificator.git"
  }
}
